package app.veyra;
import android.app.*;import android.content.*;import android.os.*;import android.view.*;import android.widget.*;import org.json.*;import org.junit.*;import org.junit.runner.RunWith;import org.robolectric.*;import org.robolectric.annotation.Config;import org.robolectric.android.controller.ActivityController;import java.lang.reflect.*;import static org.junit.Assert.*;
@RunWith(RobolectricTestRunner.class) @Config(sdk=28)
public class DownloadsPageTest {
 @Before public void clear(){RuntimeEnvironment.getApplication().getSharedPreferences("downloads",0).edit().clear().commit();}
 private Button button(View v,String text){if(v instanceof Button&&((Button)v).getText().toString().equals(text))return (Button)v;if(v instanceof ViewGroup)for(int i=0;i<((ViewGroup)v).getChildCount();i++){Button b=button(((ViewGroup)v).getChildAt(i),text);if(b!=null)return b;}return null;}
 private void render(DownloadsActivity a)throws Exception{Method m=DownloadsActivity.class.getDeclaredMethod("render");m.setAccessible(true);m.invoke(a);View root=a.getWindow().getDecorView();root.measure(View.MeasureSpec.makeMeasureSpec(1080,View.MeasureSpec.EXACTLY),View.MeasureSpec.makeMeasureSpec(1920,View.MeasureSpec.EXACTLY));root.layout(0,0,1080,1920);}
 @Test public void completedCopyOpensCacheOnlyPlayback()throws Exception{String id="aaaaaaaa-aaaa-aaaa-aaaa-aaaaaaaaaaaa";OfflineStore.save(RuntimeEnvironment.getApplication(),id,new JSONObject().put("title","Offline film").put("state","complete").put("url","https://example.com/movie.mp4").put("mime","video/mp4"));try(ActivityController<DownloadsActivity> c=Robolectric.buildActivity(DownloadsActivity.class).setup()){render(c.get());Button play=button(c.get().getWindow().getDecorView(),"Play offline");assertNotNull(play);play.performClick();Intent launched=Shadows.shadowOf(c.get()).getNextStartedActivity();assertEquals(id,launched.getStringExtra("offlineId"));assertFalse(launched.hasExtra("playback"));}}
 @Test public void transfersTabSurvivesRecreation()throws Exception{Intent intent=new Intent(RuntimeEnvironment.getApplication(),DownloadsActivity.class).putExtra("showTransfers",true);try(ActivityController<DownloadsActivity> c=Robolectric.buildActivity(DownloadsActivity.class,intent).setup()){render(c.get());assertTrue(button(c.get().getWindow().getDecorView(),"Transfers").isSelected());Bundle saved=new Bundle();c.saveInstanceState(saved);try(ActivityController<DownloadsActivity> restored=Robolectric.buildActivity(DownloadsActivity.class).create(saved).start().resume()){render(restored.get());assertTrue(button(restored.get().getWindow().getDecorView(),"Transfers").isSelected());}}}
}
